#ifndef XENON_OVERLAY_CHROME_BROWSER_IPC_XENON_WORKER_MESSAGE_H_
#define XENON_OVERLAY_CHROME_BROWSER_IPC_XENON_WORKER_MESSAGE_H_

#include <memory>
#include <vector>

#include "v8/include/v8-array-buffer.h"
#include "v8/include/v8-local-handle.h"
#include "v8/include/v8-persistent-handle.h"

namespace xenon::ipc {
// Distinguishes clone failures generated by the serializer from exceptions
// thrown by application getters, without trusting public name/code fields.
bool IsWorkerDataCloneError(v8::Local<v8::Context> context,
                            v8::Local<v8::Value> value);
// Contains no V8 handles and may cross threads. BackingStore lifetime is shared
// by V8 across isolates; it is not a pointer into either isolate's heap.
struct WorkerMessage {
  std::vector<uint8_t> bytes;
  std::vector<std::shared_ptr<v8::BackingStore>> transferred;
  std::vector<std::shared_ptr<v8::BackingStore>> shared;
  v8::MaybeLocal<v8::Value> Deserialize(v8::Local<v8::Context> context);
};

// Must remain on the sending isolate's thread. Serialize first; only commit
// after the destination has accepted ownership, so failed clones never detach
// any buffer. The returned WorkerMessage alone is safe to pass to a thread.
class PreparedWorkerMessage {
 public:
  static std::unique_ptr<PreparedWorkerMessage> Serialize(
      v8::Local<v8::Context> context,
      v8::Local<v8::Value> value,
      v8::Local<v8::Value> transfer_list);
  ~PreparedWorkerMessage();
  std::unique_ptr<WorkerMessage> Commit(v8::Isolate* isolate);
  // Queue accounting includes transferred/shared backing stores, which do
  // not occur in the serializer's byte stream. Saturates at SIZE_MAX.
  size_t message_size() const;

 private:
  PreparedWorkerMessage();
  std::unique_ptr<WorkerMessage> message_;
  std::vector<v8::Global<v8::ArrayBuffer>> sources_;
};
}  // namespace xenon::ipc
#endif
